// Read rolling context from workflow static data and prepare Claude payload.
const staticData = $getWorkflowStaticData('global');
const messageHistory = staticData.messageHistory || [];

const raw = $input.first().json;
const data = raw.body || raw;
const group      = data.group      || 'Unknown Group';
const message    = data.message    || '';
const timestamp  = data.timestamp  || new Date().toISOString();
const message_id = data.message_id || null;
const chat_id    = data.chat_id    || null;

// Build context block from last 6 stored messages
const recent = messageHistory.slice(-6);
const ctxLines = recent.map(function(h) { return '[' + h.group + '] ' + h.message; });
const contextBlock = recent.length > 0
  ? 'RECENT MESSAGES (background context only):\n' + ctxLines.join('\n') + '\n\n'
  : '';

const systemPrompt = [
  'You are a relevance filter for a US B2 visa appointment slot monitoring system watching Telegram groups in India.',
  '',
  'Decide if the LATEST MESSAGE is relevant to B2 visa appointment SLOT AVAILABILITY — meaning slots exist, just opened, or became available at a US consulate.',
  '',
  'FORWARD (relevant=true) when the message:',
  '- Reports that appointment slots are open or have just opened',
  '- Someone found or successfully booked an available slot',
  '- Mentions available dates at specific consulates (Chennai, Mumbai, Hyderabad, Delhi, Kolkata, Bangalore)',
  '- Reports cancellations that freed up slots',
  '- Describes a tool or script that detected open slots',
  '',
  'FILTER (relevant=false) only when the message is clearly:',
  '- A general visa application or document requirements question',
  '- A visa interview result or experience (approved/denied/attended)',
  '- Off-topic conversation, greetings, jokes, or spam',
  '- Admin notices or bot messages unrelated to slot availability',
  '',
  'CRITICAL RULE: When uncertain, ALWAYS forward (relevant=true). Missing a real slot alert is far worse than a false positive.',
  '',
  'Reply with ONLY a single line of valid JSON, e.g.: {"relevant": true, "reason": "brief reason"}'
].join('\n');

const userContent = contextBlock + 'LATEST MESSAGE TO CLASSIFY:\n[' + group + ']: ' + message;

// Save to history now (before the API call)
messageHistory.push({ group: group, message: message, timestamp: timestamp });
staticData.messageHistory = messageHistory.slice(-10);

return [{ json: { group: group, message: message, timestamp: timestamp, message_id: message_id, chat_id: chat_id, systemPrompt: systemPrompt, userContent: userContent } }];

// Pull original message fields from Load Context node
const prev = $('Load Context').first().json;
const group      = prev.group;
const message    = prev.message;
const timestamp  = prev.timestamp;
const message_id = prev.message_id;
const chat_id    = prev.chat_id;

// Parse Claude's JSON decision from the HTTP response
let relevant = true;
let reason   = 'parse error, defaulting to forward';

try {
  const resp = $input.first().json;
  if (resp && resp.content && resp.content[0] && resp.content[0].text) {
    const text  = resp.content[0].text.trim();
    const start = text.indexOf('{');
    const end   = text.lastIndexOf('}');
    if (start !== -1 && end !== -1) {
      const parsed = JSON.parse(text.slice(start, end + 1));
      relevant = parsed.relevant !== false; // default true unless explicitly false
      reason   = parsed.reason || '';
    }
  }
} catch (err) {
  reason = 'parse error: ' + err.message;
}

console.log('[' + (relevant ? 'FORWARD' : 'FILTER') + '] ' + reason + ' | ' + (message || '').slice(0, 80));

return [{ json: { group: group, message: message, timestamp: timestamp, message_id: message_id, chat_id: chat_id, relevant: relevant, reason: reason } }];

const data = $input.first().json;

const group     = data.group     || 'Unknown Group';
const message   = data.message   || '';
const timestamp = data.timestamp || new Date().toISOString();
const reason    = data.reason    || '';

const ts = new Date(timestamp).toLocaleString('en-US', {
  timeZone: 'America/Chicago',
  dateStyle: 'medium',
  timeStyle: 'short'
});

const preview = message.length > 500 ? message.slice(0, 500) + '\u2026' : message;

const slackText = [
  ':passport_control: *B2 Visa Slot Alert*',
  '',
  '*Group:* ' + group,
  '*Time:*  ' + ts + ' CT',
  '',
  '*Message:*',
  preview
].join('\n');

return [{ json: { slackText: slackText, group: group, message: message, timestamp: timestamp, reason: reason } }];
